import StatusBadge from '../../components/StatusBadge';
import { useAcknowledgeNotification } from '../../hooks/useCommand';
import { useOnyxQuery } from '../../hooks/useQuery';
import type { NotificationProjection } from '../../types/query';

export default function NotificationsPage() { const query = useOnyxQuery<NotificationProjection>('notification.list'); const acknowledge = useAcknowledgeNotification(); return <div className="page-stack"><header className="page-header"><div><p className="eyebrow">Delivery center</p><h1>Notifications</h1><p>Acknowledgment is sent to the server immediately. Failed commands are never queued locally.</p></div><button className="button-secondary" onClick={() => query.refetch()}>Refresh</button></header><section className="panel"><div className="panel-heading"><h2>Operational alerts</h2><span>{query.data?.data.filter((item) => item.status === 'unacknowledged').length ?? 0} unacknowledged</span></div><div className="card-list">{query.data?.data.map((item) => <article className="notification-card" key={item.id}><div className="notification-content"><div className="card-title-row"><h3>{item.title}</h3><StatusBadge status={item.status} /></div><p>{item.message}</p><small>{new Date(item.created_at).toLocaleString()} · {item.source_type}</small></div>{item.status === 'unacknowledged' ? <button className="button-primary" disabled={acknowledge.isPending} onClick={() => acknowledge.mutate(item)}>{acknowledge.isPending ? 'Sending…' : 'Acknowledge'}</button> : <span className="completed-label">Acknowledged</span>}</article>)}</div></section></div>; }
